# --- Front-end single-file guard (R6 target).
JS_CEILING = {                               # R6: ES-module split of the front-end. Lower as families move out.
    "ui/notebook_main.js": 1215,             # 2026-08-02: +11 for the SCALAR-HANDOFF button wiring (the modal itself lives in ui/notebook_handoff.js) and for the comment on a defect found while wiring it — `/api/notebook/session` names the field `backend`, so reading `primary_backend` fell back to 'maxima' in EVERY session and the Julia-only buttons (Wick 収縮 / 演算子展開) never appeared at all. Measured 1211. // 2685 → 1145 (utils + numeric + timeline + input + advise + persistence extracted)
    "ui/notebook_numeric.js": 800,           # numeric fork/ChatBot/graph modals + card renderers
    "ui/notebook_timeline.js": 200,          # pure timeline card / entry HTML renderers
    "ui/notebook_input.js": 250,             # input serialization + math-token insertion + handwriting modal
    "ui/notebook_advise.js": 250,            # LLM adviser modal (status/dropdown/submit/save-as-memo)
    "ui/notebook_persistence.js": 400,       # session save/load/export/shutdown/autosave
}


def _py_files():
    for root in WATCH_DIRS:
        for dp, _, fns in os.walk(os.path.join(REPO_ROOT, root)):
            for fn in fns:
                if fn.endswith(".py"):
                    full = os.path.join(dp, fn)
                    yield os.path.relpath(full, REPO_ROOT).replace(os.sep, "/")


def _line_count(rel):
    with open(os.path.join(REPO_ROOT, rel), encoding="utf-8") as f:
        return sum(1 for _ in f)


def _functions(rel):
    """Yield (name, line_length) for every def/async def in a file."""
    try:
        tree = ast.parse(open(os.path.join(REPO_ROOT, rel), encoding="utf-8").read())
    except SyntaxError:
        return
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            yield node.name, (node.end_lineno or node.lineno) - node.lineno + 1


# ---------------------------------------------------------------------------
# File-size ratchet
# ---------------------------------------------------------------------------

def test_watched_files_within_ceilings():
    over = []
    for rel, ceiling in FILE_CEILINGS.items():
        n = _line_count(rel)
        if n > ceiling:
            over.append(f"{rel}: {n} > {ceiling}")
    assert not over, (
        "File(s) grew past their hygiene ceiling. Refactor to shrink, or "
        "raise the ceiling in tests/test_code_hygiene.py with a reason:\n  "
        + "\n  ".join(over))


def test_no_untracked_large_file():
    """A .py file at/over FILE_GUARD lines that isn't in FILE_CEILINGS is a new
    hotspot — list it (with a ceiling) or split it."""
    untracked = []
    for rel in _py_files():
        if _line_count(rel) >= FILE_GUARD and rel not in FILE_CEILINGS:
            untracked.append(f"{rel}: {_line_count(rel)}")
    assert not untracked, (
        "New large file(s) not tracked by the ratchet — add to FILE_CEILINGS "
        "or split:\n  " + "\n  ".join(untracked))


# ---------------------------------------------------------------------------
# Function-size ratchet
# ---------------------------------------------------------------------------

def test_watched_functions_within_ceilings():
    over = []
    for (rel, name), ceiling in FUNC_CEILINGS.items():
        lengths = [L for fn, L in _functions(rel) if fn == name]
        if not lengths:
            over.append(f"{rel}:{name} not found (renamed/removed? update the table)")
            continue
        biggest = max(lengths)
        if biggest > ceiling:
            over.append(f"{rel}:{name}: {biggest} > {ceiling}")
    assert not over, (
        "Function(s) grew past their hygiene ceiling. Extract helpers to "
        "shrink, or raise the ceiling with a reason:\n  " + "\n  ".join(over))


def test_no_untracked_large_function():
    """A function over FUNC_GUARD lines not in FUNC_CEILINGS is a new giant —
    list it or extract helpers."""
    untracked = []
    for rel in _py_files():
        for name, length in _functions(rel):
            if length > FUNC_GUARD and (rel, name) not in FUNC_CEILINGS:
                untracked.append(f"{rel}:{name}: {length}")
    assert not untracked, (
        "New large function(s) not tracked by the ratchet — add to "
        "FUNC_CEILINGS or extract helpers:\n  " + "\n  ".join(untracked))


# ---------------------------------------------------------------------------
# Broad-except budget
# ---------------------------------------------------------------------------

def test_broad_except_budget():
    exc_exception = 0
    bare = 0
    for rel in _py_files():
        for line in open(os.path.join(REPO_ROOT, rel), encoding="utf-8"):
            s = line.strip()
            if s.startswith("except Exception") and (
                    len(s) == len("except Exception")
                    or not s[len("except Exception")].isalnum()):
                exc_exception += 1
            elif s.rstrip() == "except:":
                bare += 1
    assert exc_exception <= EXCEPT_EXCEPTION_CEILING, (
        f"'except Exception' count {exc_exception} > ceiling "
        f"{EXCEPT_EXCEPTION_CEILING}. New broad catches need a reason comment; "
        "narrow the exception or raise the ceiling deliberately.")
    assert bare <= BARE_EXCEPT_CEILING, (
        f"bare 'except:' count {bare} > {BARE_EXCEPT_CEILING} — always name the "
        "exception type.")


# ---------------------------------------------------------------------------
# CAS separation (docs/32 Phase 2b, open_items AUDIT-SHARED-CAS-LEAK)
#
# The backend CAS is PLUGGABLE (Core Principle #10): adding a third one must not
# require editing shared code.  These are the shared layers — every CAS-specific
# decision they make has to go through a BackendHandler / resolver hook.
#
# Comments and docstrings naming Maxima or Julia are FINE and wanted: they
# explain why a hook exists.  What is counted here is CAS-specific *behaviour*:
# importing a backend module, branching on backend identity, or type-checking a
# concrete handler.  All three were at 0 when this ratchet landed — it exists so
# they stay there.
# ---------------------------------------------------------------------------

SHARED_LAYERS: tuple[str, ...] = (
    "notebook/runtime/backend_handler.py",
    "notebook/runtime/semantic_resolver.py",
    "notebook/runtime/code_generator.py",
    "notebook/runtime/shared_parser.py",
    "notebook/runtime/latex_converter.py",
    "notebook/runtime/llm_supervisor.py",
    "notebook/runtime/operation_validator.py",
    "notebook/engine.py",
    "ui/notebook_bridge.py",
    "ui/debug_repl.py",
)
# backend_factory.py is the ONE place allowed to name the backends: owning the
# name registry, the mode→backend defaults and both directions between them is
# its entire purpose.
CAS_IMPORT_CEILING = 0        # `from|import ...maxima|julia...` in SHARED_LAYERS
CAS_BRANCH_CEILING = 0        # `primary_backend == "<name>"` in SHARED_LAYERS
CAS_ISINSTANCE_CEILING = 0    # isinstance(..., MaximaBackendHandler/Julia...)
CAS_LITERAL_CEILING = 0       # a bare "maxima"/"julia_full" string in the code

_CAS_NAME_RE = re.compile(r"maxima|julia", re.I)
# A string whose WHOLE value is a backend name — a default argument
# (`primary_backend: str = "maxima"`), a lookup table, a comparison.  Anchored,
# so prose in a docstring that merely mentions a backend never matches.
_CAS_NAME_LITERAL_RE = re.compile(r"^(?:maxima|julia(?:_\w+)?)$", re.I)


def _scan_shared_layers() -> "dict[str, list[str]]":
    """Scan the shared layers via AST, so COMMENTS and DOCSTRINGS naming a
    backend are structurally excluded — they are documentation, and this
    codebase deliberately has a lot of it explaining why each hook exists.
    Only executable references count."""
    hits: dict[str, list[str]] = {"import": [], "branch": [], "isinstance": [],
                                  "literal": []}
    for rel in SHARED_LAYERS:
        path = os.path.join(REPO_ROOT, rel)
        if not os.path.exists(path):
            continue
        src = open(path, encoding="utf-8").read()
        for node in ast.walk(ast.parse(src)):
            if isinstance(node, ast.Constant) and isinstance(node.value, str) \
                    and _CAS_NAME_LITERAL_RE.match(node.value):
                hits["literal"].append(f"{rel}:{node.lineno}: {node.value!r}")
            if isinstance(node, ast.ImportFrom):
                if node.module and _CAS_NAME_RE.search(node.module):
                    hits["import"].append(f"{rel}:{node.lineno}: from {node.module}")
            elif isinstance(node, ast.Import):
                for a in node.names:
                    if _CAS_NAME_RE.search(a.name):
                        hits["import"].append(f"{rel}:{node.lineno}: import {a.name}")
            elif isinstance(node, ast.Compare):
                # Only a comparison of primary_backend against a backend NAME is
                # a branch on backend identity.  `primary_backend is None`
                # (the constructor's default-argument check) is not.
                sides = [node.left, *node.comparators]
                names = {getattr(s, "attr", None) or getattr(s, "id", None)
                         for s in sides}
                literals = [
                    c.value for s in sides
                    for c in ([s] if isinstance(s, ast.Constant) else
                              getattr(s, "elts", []))
                    if isinstance(c, ast.Constant) and isinstance(c.value, str)
                ]
                if "primary_backend" in names and any(
                        _CAS_NAME_RE.search(v) for v in literals):
                    hits["branch"].append(
                        f"{rel}:{node.lineno}: primary_backend == "
                        f"{literals!r}")
            elif isinstance(node, ast.Call):
                if getattr(node.func, "id", None) != "isinstance":
                    continue
                for arg in ast.walk(node):
                    nm = getattr(arg, "id", None) or getattr(arg, "attr", None)
                    if nm and _CAS_NAME_RE.search(nm):
                        hits["isinstance"].append(f"{rel}:{node.lineno}: isinstance({nm})")
                        break
    return hits


def test_shared_layers_have_no_cas_specific_code():
    hits = _scan_shared_layers()
    for kind, ceiling, fix in (
        ("import", CAS_IMPORT_CEILING,
         "move the logic into the BackendHandler subclass, or lift the "
         "CAS-neutral part into a neutral module (see "
         "latex_converter.TEX_GREEK_TO_NAME)"),
        ("branch", CAS_BRANCH_CEILING,
         "add a capability hook to BackendHandler and call it instead"),
        ("isinstance", CAS_ISINSTANCE_CEILING,
         "add a hook to BackendHandler and override it in that subclass"),
        ("literal", CAS_LITERAL_CEILING,
         "ask backend_factory (default_backend_for_mode / "
         "session_mode_for_backend) instead of naming a CAS here; a backend "
         "name as a DEFAULT argument is the worst case — a caller that forgets "
         "the argument then silently gets that CAS"),
    ):
        found = hits[kind]
        assert len(found) <= ceiling, (
            f"{len(found)} CAS-specific '{kind}' site(s) in shared layers "
            f"> ceiling {ceiling}. The CAS is pluggable — {fix}. "
            "Raising this ceiling means giving that up:\n  "
            + "\n  ".join(found))


# ---------------------------------------------------------------------------
# Front-end single-file guard (R6 target)
# ---------------------------------------------------------------------------

def test_frontend_single_file_within_ceiling():
    over = []
    for rel, ceiling in JS_CEILING.items():
        n = _line_count(rel)
        if n > ceiling:
            over.append(f"{rel}: {n} > {ceiling}")
    assert not over, (
        "Front-end file grew past its ceiling (R6 will split it into ES "
        "modules). Shrink or raise deliberately:\n  " + "\n  ".join(over))
